	private static void copyExact(Path source, Path destination, long expectedBytes, StringBuilder inventory)
			throws IOException {
		if (Files.size(source) != expectedBytes) {
			throw new IOException("DIAGNOSTIC_COPY_SIZE: " + source);
		}
		String before = sha256(source);
		Files.copy(source, destination);
		if (Files.size(source) != expectedBytes || Files.size(destination) != expectedBytes
				|| !before.equals(sha256(source)) || !before.equals(sha256(destination))) {
			throw new IOException("DIAGNOSTIC_COPY_HASH: " + source);
		}
		inventory.append(source.getFileName())
				.append('\t')
				.append(expectedBytes)
				.append('\t')
				.append(before)
				.append('\n');
	}

	private static String sha256(Path path) throws IOException {
		try {
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			try (var input = new DigestInputStream(Files.newInputStream(path), digest)) {
				input.transferTo(OutputStream.nullOutputStream());
			}
			return HexFormat.of().formatHex(digest.digest());
		} catch (NoSuchAlgorithmException exception) {
			throw new AssertionError(exception);
		}
	}
